'use strict';
const M = window.StudioModel;
const $ = (s, root = document) => root.querySelector(s);
const escapeHTML = value => String(value ?? '').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const e = escapeHTML;
const brandIconSet = window.SaziBrandIcons;
const pageIconNames = {overview:'home',videos:'videos',create:'videos',video:'videos',plan:'plan',analytics:'analytics',agent:'agent',niche:'niche',studio:'studio',brand:'brand',channels:'channels',leads:'leads',checks:'checks'};
const panelIconNames = {'Собираем ролик':'videos','Черновик готов к работе':'videos','Куда публикуем':'publications','Публикации':'publications','Сценарий ролика':'videos','Журнал агента · демонстрация':'agent','Динамика просмотров':'analytics','От внимания к заявке':'leads'};
const icons = name => {
  const key = brandIconSet.aliases[name] || name;
  const source = brandIconSet.sources[key];
  return source ? `<span class="brand-pictogram" data-brand-icon="${key}" aria-hidden="true"><img src="${source}" alt="" width="32" height="32" decoding="async"></span>` : `<svg aria-hidden="true"><use href="#i-${name}"/></svg>`;
};
const storage = {getItem:key=>{try{return localStorage.getItem(key);}catch{return null;}},setItem:(key,value)=>{try{localStorage.setItem(key,value);}catch{throw new Error('Хранилище недоступно');}}};
let state = M.load(storage), theme = document.documentElement.dataset.theme === 'dark' ? 'dark' : 'light';
const main = $('#main-content'), media = new Map();
let disposeMascot=()=>{};
let ui={filter:'all',query:'',planView:'list',week:0,videoTab:'publish',period:14,analyticsChannel:'all',studioTab:'week',leadsFilter:'all',carousel:0};
let wizard={}, wizardStep=1, undoState=null, toastTimer, storageWarning=false;
const navItems=[['overview','Главная','home'],['videos','Ролики','video'],['plan','План и автопилот','calendar'],['analytics','Аналитика','chart'],['agent','Агент-маркетолог','agent'],['niche','Анализ ниши','flame'],['studio','Instagram-студия','studio'],['brand','Бренд и товары','box'],['channels','Каналы и API','plug'],['leads','Заявки (команда)','leads'],['checks','Проверка API','shield']];
const statusNames={published:'Опубликован',ready:'Готов',planned:'В плане',draft:'Черновик',generating:'Собирается'};
function statusBadge(status){const safe=statusNames[status]?status:'draft';return `<span class="status status-${safe}">${statusNames[safe]}</span>`;}
function fmt(value){return new Intl.NumberFormat('ru-RU').format(value||0);}
function shortDate(date){return new Intl.DateTimeFormat('ru-RU',{day:'numeric',month:'short'}).format(new Date(`${date}T12:00:00Z`));}
function duration(value){return `${Math.floor(Number(value)/60)}:${String(Number(value)%60).padStart(2,'0')}`;}
function route(){const [page='overview',id='']=location.hash.slice(1).split('/');return {page:page||'overview',id:decodeURIComponent(id)};}
function go(page,id=''){const hash=`#${page}${id?'/'+encodeURIComponent(id):''}`;if(location.hash===hash)render();else location.hash=hash;}
function save(){if(!M.save(storage,state)&&!storageWarning){storageWarning=true;toast('Браузер запретил сохранение. Изменения доступны до закрытия страницы.');}}
function applyTheme(next,persist=true){theme=next==='dark'?'dark':'light';document.documentElement.dataset.theme=theme;$('meta[name="theme-color"]').content=theme==='light'?'#F2F5FA':'#0A0C10';document.querySelectorAll('[data-theme-choice]').forEach(b=>b.setAttribute('aria-pressed',String(b.dataset.themeChoice===theme)));if(persist){try{localStorage.setItem('sazi-content-theme',theme);}catch{}}}
function button(action,label,icon='',extra=''){return `<button type="button" class="btn ${extra}" data-action="${action}">${icon?icons(icon):''}${label}</button>`;}
function heading(title,subtitle,action=''){const icon=pageIconNames[route().page];return `<div class="page-heading"><div class="page-heading-title">${icon?icons(icon):''}<div><h1>${title}</h1><p>${subtitle}</p></div></div>${action}</div>`;}
function panel(title,content,extra=''){return `<section class="work-panel ${extra}">${title?`<div class="panel-heading"><h2>${panelIconNames[title]?icons(panelIconNames[title]):''}${title}</h2></div>`:''}${content}</section>`;}
function select(name,options,value,extra=''){return `<select name="${name}" id="${name}" ${extra}>${options.map(o=>{const [key,label]=Array.isArray(o)?o:[o,o];return `<option value="${e(key)}" ${String(key)===String(value)?'selected':''}>${e(label)}</option>`;}).join('')}</select>`;}
function field(label,content){return `<label class="input-field"><span>${label}</span>${content}</label>`;}
function textField(name,label,value='',placeholder='',extra=''){return field(label,`<input name="${name}" id="${name}" value="${e(value)}" placeholder="${e(placeholder)}" ${extra}>`);}
function tabs(group,items,active){return `<div class="workspace-tabs" role="group" aria-label="${e(group==='studioTab'?'Инструменты Instagram':'Раздел')}">${items.map(([id,label])=>`<button class="${active===id?'active':''}" type="button" data-tab-group="${group}" data-tab="${id}" aria-pressed="${active===id}">${label}</button>`).join('')}</div>`;}
function demoNote(text='Демонстрация интерфейса: действия сохраняются локально, без обращения к внешним сервисам.'){return `<div class="mode-note">${icons('grid')}<span>${text}</span></div>`;}
function formError(){return '<p id="form-error" class="form-error" role="alert"></p>';}
function toast(message,undo=false){clearTimeout(toastTimer);$('#toast').innerHTML=`<span>${e(message)}</span>${undo?'<button type="button" data-action="undo">Отменить</button>':''}`;$('#toast').classList.add('show');toastTimer=setTimeout(()=>$('#toast').classList.remove('show'),undo?8000:4200);}
function rememberUndo(){undoState=M.clone(state);}
function openModal(title,body){$('#modal-content').innerHTML=`<div class="modal-heading"><h2 id="modal-title">${title}</h2><button type="button" class="icon-btn" data-action="close-modal" aria-label="Закрыть">${icons('close')}</button></div>${body}`;$('#modal').showModal();}
function download(name,content,type='text/plain;charset=utf-8'){const url=URL.createObjectURL(new Blob([content],{type}));const link=document.createElement('a');link.href=url;link.download=name;link.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
function coverMarkup(v){const number=[1,2,3,4].includes(v.cover)?v.cover:5;const titles={v1:'Один человек.<br>Целая студия.',v2:'Контент,<br>который<br><em>работает.</em>',v3:'7 идей<span>для твоего<br>следующего ролика</span>',v4:'Ваш голос.<br>Любой язык.',v5:'Как<br>рождается<br>идея.',v6:'Меньше рутины.<br><em>Больше<br>смысла.</em>',v7:'1 тема<span>пять новых<br>форматов</span>',v8:'Твой бренд.<br>Новое<br>звучание.'};return `<div class="cover cover-${number}" aria-hidden="true"><div class="cover-top"><span class="cover-logo">${e(state.brand.name.toLowerCase())}.</span><span class="cover-time">${duration(v.duration)}</span></div><div class="cover-orb">${number===4?'<i></i>'.repeat(8):''}</div><div class="cover-title">${titles[v.id]||e(v.title)}</div><div class="cover-caption">CREATE. CONNECT. REPEAT.</div><span class="cover-play">${icons('play')}</span></div>`;}
function videoCard(v){return `<a class="video-card" href="#video/${e(v.id)}" aria-label="Открыть ролик: ${e(v.title)}">${coverMarkup(v)}<div class="video-info"><h3>${e(v.title)}</h3><p>${statusBadge(v.status)}<span>${e(v.format.replace('Instagram ','').replace('YouTube ',''))} · ${shortDate(M.day(v.createdAt||Date.now()))}</span></p></div></a>`;}
function metric(label,value,foot='',icon='chart'){return `<article class="metric"><div class="metric-top">${label}${icons(icon)}</div><div class="metric-value">${value}</div><div class="metric-foot">${foot}</div></article>`;}
function overviewPage(){const t=M.totals(state);return `${heading('Твоя контент-студия','От первой идеи до результата — весь процесс в одном месте.')}<section class="hero"><div class="hero-copy"><span class="eyebrow">${icons('spark')}ОТ ИДЕИ ДО ПУБЛИКАЦИИ</span><h2>Больше идей.<br><span class="gradient-text">Меньше рутины.</span></h2><p>Загрузи материалы, выбери формат<br>и собери свой следующий ролик.</p><div class="hero-actions"><a class="btn btn-gradient" href="#create">${icons('plus')}Создать ролик</a><a href="#niche" class="text-link">Что залетает ${icons('arrow')}</a><a href="#agent" class="text-link">Спросить агента</a></div></div><div class="hero-art hero-flower-art" aria-hidden="true">${window.MillMascot.markup()}<div class="art-tag idea">${icons('agent')}Идея</div><div class="art-tag script">${icons('file')}Сценарий</div><div class="art-tag ready">${icons('videos')}Готовый ролик</div></div></section><div class="section-head"><h2>${icons('analytics')}Результаты за 14 дней</h2><span class="section-meta">Демо-данные</span></div><div class="metrics">${metric('Просмотры',fmt(t.views),'Пример результатов контента','trend')}${metric('Переходы',fmt(t.clicks),`CTR ${t.views?(t.clicks/t.views*100).toFixed(1):0}%`,'link')}${metric('Заявки',fmt(t.leads),'Из публикаций в демо-проекте','leads')}${metric('Ролики',fmt(t.videos),`Публикаций: ${t.published}`,'video')}</div><div class="section-head"><h2>${icons('videos')}Последние ролики</h2><a href="#videos" class="text-link">Все ролики ${icons('arrow')}</a></div><div class="content-grid">${state.videos.slice(0,4).map(videoCard).join('')}</div><div class="quick-tools"><a href="#niche">${icons('flame')}<div><h3>Анализ ниши</h3><p>Форматы, хуки и идеи для твоего бренда</p></div>${icons('arrow')}</a><a href="#plan">${icons('calendar')}<div><h3>План и автопилот</h3><p>Идей в плане: ${state.plan.length} · ${state.autopilot.enabled?'автопилот включён':'готов к настройке'}</p></div>${icons('arrow')}</a><a href="#studio">${icons('studio')}<div><h3>Instagram-студия</h3><p>Карусели, сторис и контент на неделю</p></div>${icons('arrow')}</a></div>`;}
function videosPage(){return `${heading('Ролики','Черновики, процессы сборки и готовые публикации.',`<a href="#create" class="btn btn-gradient">${icons('plus')}Создать ролик</a>`)}<div class="toolbar">${tabs('filter',[['all','Все'],['generating','В работе'],['ready','Готовы'],['planned','В плане'],['published','Опубликованы'],['draft','Черновики']],ui.filter)}<label class="search-field">${icons('search')}<input id="video-search" value="${e(ui.query)}" placeholder="Найти ролик" aria-label="Найти ролик"></label></div><div class="content-grid library-grid" id="video-library">${filteredVideos()}</div>`;}
function filteredVideos(){const found=state.videos.filter(v=>(ui.filter==='all'||v.status===ui.filter)&&v.title.toLowerCase().includes(ui.query.toLowerCase()));return found.length?found.map(videoCard).join(''):'<div class="empty-state">Пока нет роликов с такими параметрами. Измени фильтр или создай новый.</div>';}
function ensureWizard(){wizard={title:'',brief:'',productId:state.products[0]?.id||'',format:M.platforms[0],duration:30,method:'Проблема → решение',voice:'Спокойный',language:'Русский',assets:[],...wizard};}
function createPage(){ensureWizard();const v={id:'preview',title:wizard.title||'Твоя следующая идея.',cover:5,duration:Number(wizard.duration)||30};let content='';if(wizardStep===1)content=`<div class="form-grid">${field('Бренд',`<input value="${e(state.brand.name)}" disabled>`)}${field('Товар или услуга',select('productId',state.products.map(p=>[p.id,p.name]),wizard.productId))}</div>${textField('title','Название или идея ролика',wizard.title,'Например: одна идея превращается в неделю контента','required maxlength="180"')}${field('Что показать и какую мысль донести',`<textarea name="brief" rows="4" maxlength="2000" placeholder="Опиши продукт, аудиторию и результат">${e(wizard.brief)}</textarea>`)}<div class="upload-zone">${icons('upload')}<strong>Свои кадры и фото товара</strong><span>Материалы используются только в этом браузере</span><label class="btn"><input id="wizard-files" type="file" accept="image/*,video/*" multiple>Выбрать файлы</label></div>${assetList(wizard.assets)}<a href="#brand" class="text-link">Настроить бренд и библиотеку материалов ${icons('arrow')}</a>`;
if(wizardStep===2)content=`<div class="form-grid">${field('Формат подачи',select('method',M.patterns.map(p=>p.type),wizard.method))}${field('Площадка',select('format',M.platforms,wizard.format))}${field('Длительность',select('duration',[[15,'15 секунд'],[30,'30 секунд'],[45,'45 секунд'],[60,'60 секунд']],wizard.duration))}${field('Соотношение сторон','<input value="9:16 · вертикальный ролик" disabled>')}${field('Голос',select('voice',['Спокойный','Энергичный','Без озвучки'],wizard.voice))}${field('Язык',select('language',['Русский','English'],wizard.language))}</div><div class="info-banner">${icons('spark')}<p>Стиль текста берётся из настроек бренда. В демонстрации используется заготовка сценария, без вызова AI.</p></div>`;
if(wizardStep===3)content=`<div class="review-list"><div><span>Идея</span><strong>${e(wizard.title)}</strong></div><div><span>Товар</span><strong>${e(state.products.find(p=>p.id===wizard.productId)?.name||'Не выбран')}</strong></div><div><span>Формат</span><strong>${e(wizard.method)} · ${e(wizard.format)}</strong></div><div><span>Настройки</span><strong>${wizard.duration} сек · ${e(wizard.voice)} · ${e(wizard.language)}</strong></div><div><span>Материалы</span><strong>${wizard.assets?.length||0} файлов</strong></div></div>${demoNote('Демо-сборка покажет этапы, журнал и готовую карточку ролика. Настоящее видео не генерируется.')}`;
return `${heading('Создать ролик','Твои материалы, голос бренда и подходящий формат.')}<div class="creation-steps">${['Материалы','Формат','Запуск'].map((label,i)=>`<span class="${wizardStep===i+1?'active':wizardStep>i+1?'done':''}"><b>${wizardStep>i+1?icons('check'):i+1}</b>${label}</span>`).join('')}</div><div class="editor-layout"><section class="work-panel"><form id="wizard-form">${content}${formError()}<div class="form-actions">${wizardStep>1?button('wizard-back','Назад','back'):button('save-draft','Сохранить черновик','file')}<button type="submit" class="btn btn-gradient">${wizardStep===3?'Показать демо-сборку':'Продолжить'}${icons(wizardStep===3?'spark':'arrow')}</button></div></form></section><aside class="preview-panel"><div class="spec-label">ПРЕВЬЮ КОМПОЗИЦИИ</div>${coverMarkup(v)}<span class="preview-caption">Обложка-заготовка · 9:16</span></aside></div>`;}
function assetList(assets=[]){return assets.length?`<div class="asset-list">${assets.map(a=>`<span>${icons(a.type?.startsWith('video')?'video':'file')}${e(a.name)}<small>${Math.ceil(a.size/1024)} КБ</small></span>`).join('')}</div>`:'';}
function journal(v){const p=v.status==='generating'?M.progress(v.startedAt,v.jobDuration):100;const log=[['/ig-viral',`Формат «${v.method}» выбран для демо-сценария.`],['Голос бренда',state.brand.tone],['Сценарий',`Хук, основная мысль, пример и финал. ${v.duration} секунд.`],['Материалы',`${v.assets?.length||0} своих файлов. Обложка и сцены в прототипе представлены макетом.`],['Монтаж','Демонстрация переходов, субтитров и музыки без рендера видео.'],['Проверка','Сценарий доступен для редактирования. Готов к демо-публикации.']];return `<div class="agent-journal">${log.slice(0,Math.min(6,Math.floor(p/17)+1)).map(([title,text])=>`<article><span>${e(title)}</span><p>${e(text)}</p></article>`).join('')}</div>`;}
function videoPage(videoId){const v=state.videos.find(v=>v.id===videoId);if(!v)return `${heading('Ролик не найден','Возможно, он был удалён.')}<a href="#videos" class="btn">В библиотеку</a>`;const working=v.status==='generating';const p=working?M.progress(v.startedAt,v.jobDuration):100;const localVideo=(v.assets||[]).find(a=>a.type.startsWith('video')&&media.has(a.id));const preview=localVideo?`<video controls playsinline src="${media.get(localVideo.id)}"></video>`:coverMarkup(v);const pubs=state.publications.filter(p=>p.videoId===v.id);let right='';if(working)right=`${panel('Собираем ролик',`<div class="job-progress"><div><strong>${M.videoSteps[Math.min(5,Math.floor(p/100*6))]}</strong><b>${p}%</b></div><progress value="${p}" max="100">${p}%</progress></div><div class="job-steps">${M.videoSteps.map((text,i)=>`<div class="${i<Math.floor(p/100*6)?'done':i===Math.floor(p/100*6)?'current':''}"><span>${i<Math.floor(p/100*6)?icons('check'):i+1}</span>${text}</div>`).join('')}</div>`)}${panel('Журнал агента · демонстрация',journal(v))}`;
else if(v.status==='draft')right=`${panel('Черновик готов к работе',`<p class="body-copy">Проверь сценарий и материалы. Затем можно посмотреть демонстрацию процесса сборки.</p><form id="script-form" data-id="${e(v.id)}">${field('Сценарий',`<textarea name="script" rows="9" maxlength="6000">${e(v.script)}</textarea>`)}<button class="btn" type="submit">Сохранить сценарий</button></form><div class="form-actions">${button('start-video','Показать демо-сборку','spark','btn-gradient')}<input type="hidden" id="current-video" value="${e(v.id)}"></div>`)}${demoNote()}`;
else right=`${tabs('videoTab',[['publish','Публикация'],['script','Сценарий'],['journal','Журнал']],ui.videoTab)}${ui.videoTab==='publish'?panel('Куда публикуем',`<form id="caption-form" data-id="${e(v.id)}">${field('Подпись к публикации',`<textarea name="caption" rows="5" maxlength="3000">${e(v.caption)}</textarea>`)}<div class="inline-meta">${button('save-caption','Сохранить подпись','check')}<a class="text-link" href="#channels">Настроить каналы ${icons('arrow')}</a></div></form><div class="connected-chips">${state.channels.filter(c=>c.connected).map(c=>`<span>${icons('globe')}${e(c.handle)}<small>${e(c.platform)}</small></span>`).join('')||'<p class="muted">Добавь демо-канал в разделе «Каналы и API».</p>'}</div>${button('open-publish','Опубликовать или запланировать','publications','btn-gradient full-width')}<input type="hidden" id="current-video" value="${e(v.id)}"><p class="small-help">Демо-режим: запись появится в проекте, без отправки в соцсеть.</p>`):ui.videoTab==='script'?panel('Сценарий ролика',`<form id="script-form" data-id="${e(v.id)}">${field('Текст и последовательность сцен',`<textarea name="script" rows="12" maxlength="6000">${e(v.script)}</textarea>`)}<div class="form-actions"><button class="btn btn-gradient" type="submit">Сохранить изменения</button>${button('copy-script','Скопировать','copy')}</div></form>`):panel('Журнал агента · демонстрация',journal(v))}${panel('Публикации',pubs.length?`<div class="publication-list">${pubs.map(pub=>{const c=state.channels.find(c=>c.id===pub.channelId);return `<article><div class="channel-icon">${icons('globe')}</div><div><strong>${e(c?.handle||'Канал удалён')}</strong><p>${e(c?.platform||'')} · ${shortDate(pub.date)}, ${pub.time}</p><small>Демо · ${fmt(v.views)} просмотров · ${fmt(v.clicks)} переходов · ${v.leads} заявок</small></div>${statusBadge(pub.status)}</article>`;}).join('')}</div>`:'<p class="body-copy">Здесь появятся запланированные и опубликованные записи.</p>')}`;
return `${heading(e(v.title),`${e(v.method)} · ${v.duration} сек · ${e(v.format)}`,`<a href="#videos" class="btn">${icons('back')}Все ролики</a>`)}<div class="video-workspace"><aside class="video-preview">${preview}${working?`<div class="preview-progress"><strong>${p}%</strong><span>Демонстрация сборки</span></div>`:''}<div class="video-tools">${button('download-materials','Скачать','download')}${button('duplicate-video','Другой вариант','refresh')}${button('delete-video','Удалить','delete','btn-icon-only')}</div><span class="preview-caption">${localVideo?'Твои исходные кадры':'Превью обложки · видео не сгенерировано'}</span></aside><div class="video-controls">${statusBadge(v.status)}${right}</div></div>`;}
function planPage(){const start=M.addDays(M.monday(Date.now()),ui.week*7);const week=Array.from({length:7},(_,i)=>M.addDays(start,i));const planned=state.publications.filter(p=>p.status==='planned');return `${heading('План и автопилот','От форматов на неделю до выхода в подключённые каналы.',`<a href="#create" class="btn btn-gradient">${icons('plus')}Добавить ролик</a>`)}<section class="work-panel autopilot-panel"><div class="panel-heading"><div><h2>Автопилот</h2><p>Настройки подготовки и выпуска роликов по плану.</p></div><button class="switch" role="switch" id="autopilot-toggle" data-action="autopilot" aria-label="Автопилот в демо-проекте" aria-checked="${state.autopilot.enabled}"></button></div><div class="autopilot-controls"><div><span class="field-caption">Роликов в неделю</span><div class="number-choices">${[2,3,4,5,7].map(n=>`<button data-action="plan-count" data-value="${n}" class="${state.autopilot.count===n?'active':''}" aria-pressed="${state.autopilot.count===n}">${n}</button>`).join('')}</div></div><div class="action-row">${button('plan-analysis','Составить план по анализу ниши','spark','btn-gradient')}${button('plan-quick','Быстрый план','calendar')}</div></div><p class="small-help">Демо-настройки сохраняются. Автопубликация на внешние площадки не выполняется.</p></section><div class="section-head"><h2>Контент-план <span class="count-label">${state.plan.length}</span></h2><div class="action-row">${tabs('planView',[['list','Список'],['calendar','Календарь']],ui.planView)}${button('clear-plan','Очистить','delete','btn-quiet')}</div></div>${ui.planView==='list'?`<div class="plan-list">${state.plan.map(item=>`<article class="plan-row"><div class="plan-date"><strong>${new Date(`${item.date}T12:00:00Z`).getUTCDate()}</strong><span>${shortDate(item.date).split(' ').slice(1).join(' ')}</span></div><div class="plan-thumb cover-${M.patterns.find(p=>p.id===item.patternId)?.cover||1}">${icons('video')}</div><div class="plan-copy"><span class="eyebrow">${e(item.type)} · ${item.time}</span><h3>${e(item.title)}</h3><p>${e(item.description)}</p></div><button type="button" class="btn" data-action="make-plan-video" data-id="${e(item.id)}">${item.videoId?'Открыть':'Сделать'}${icons('arrow')}</button></article>`).join('')||'<div class="empty-panel">План пока пуст. Составь его по анализу ниши или начни с быстрого плана.</div>'}</div>`:`<div class="week-header"><div class="action-row">${button('week-prev','Предыдущая','back','btn-quiet')}<h2>${shortDate(start)} — ${shortDate(week[6])}</h2>${button('week-next','Следующая','arrow','btn-quiet')}</div><span class="subtle-label">Москва, UTC+3</span></div><div class="calendar">${week.map(date=>`<article class="calendar-day ${date===M.day(Date.now())?'today':''}"><div class="day-label"><span>${new Intl.DateTimeFormat('ru-RU',{weekday:'short'}).format(new Date(`${date}T12:00:00Z`)).toUpperCase()}</span><span class="day-number">${Number(date.slice(-2))}</span></div>${state.plan.filter(p=>p.date===date).map(p=>`<button class="calendar-event" data-action="make-plan-video" data-id="${e(p.id)}"><time>${p.time}</time><p>${e(p.title)}</p><small>${e(p.type)}</small></button>`).join('')}</article>`).join('')}</div>`}<div class="section-head spaced"><h2>${icons('publications')}Запланированные публикации</h2><span class="section-meta">Запланировано: ${planned.length}</span></div>${panel('',planned.length?planned.map(p=>`<a class="scheduled-row" href="#video/${e(p.videoId)}">${icons('calendar')}<div><strong>${e(state.videos.find(v=>v.id===p.videoId)?.title||'Ролик')}</strong><span>${e(state.channels.find(c=>c.id===p.channelId)?.handle||'Канал')} · ${shortDate(p.date)}, ${p.time}</span></div>${icons('arrow')}</a>`).join(''):'<p class="body-copy">Открой готовый ролик и выбери дату публикации — запись появится здесь.</p>')}`;}
function analyticsPage(){const chosen=ui.analyticsChannel;const ids=new Set(state.publications.filter(p=>chosen==='all'||state.channels.find(c=>c.id===p.channelId)?.platform===chosen).map(p=>p.videoId));const rows=state.videos.filter(v=>chosen==='all'||ids.has(v.id));const factor=ui.period===7?.56:ui.period===30?1.82:1;const totals=rows.reduce((r,v)=>({views:r.views+v.views,clicks:r.clicks+v.clicks,leads:r.leads+v.leads}),{views:0,clicks:0,leads:0});const weights=[.25,.35,.3,.5,.4,.65,.52,.7,.6,.76,.69,.88,1,.85];const weightSum=weights.reduce((a,b)=>a+b,0);const points=weights.map(w=>Math.round(totals.views*factor*w/weightSum));const ceiling=Math.max(1000,Math.ceil(Math.max(...points)/1000)*1000);return `${heading('Аналитика','Просмотры, переходы и заявки — в одной цепочке.',`<div class="action-row">${select('analytics-period',[[7,'7 дней'],[14,'14 дней'],[30,'30 дней']],ui.period,'aria-label="Период аналитики"')}${select('analytics-channel',[['all','Все площадки'],...state.channels.filter(c=>c.connected).map(c=>[c.platform,c.platform])],chosen,'aria-label="Площадка аналитики"')}</div>`)}<div class="metrics">${metric('Просмотры',fmt(Math.round(totals.views*factor)),'Демо-данные','trend')}${metric('Переходы',fmt(Math.round(totals.clicks*factor)),'Из опубликованного контента','link')}${metric('Заявки',fmt(Math.round(totals.leads*factor)),'Пример атрибуции по роликам','leads')}${metric('CTR',`${totals.views?(totals.clicks/totals.views*100).toFixed(1):0}%`,'Переходы / просмотры','chart')}</div><div class="analytics-layout">${panel('Динамика просмотров',`<div class="chart-legend"><span class="legend-dot"></span>Просмотры <small>Пример за ${ui.period} дней</small></div><div class="bar-chart"><div class="chart-axis"><span>${fmt(ceiling)}</span><span>${fmt(Math.round(ceiling*2/3))}</span><span>${fmt(Math.round(ceiling/3))}</span><span>0</span></div><svg viewBox="0 0 600 220" role="img" aria-label="Демонстрационный график просмотров за выбранный период"><title>Просмотры: демонстрационная динамика</title>${[10,70,130,190].map(y=>`<line x1="0" x2="600" y1="${y}" y2="${y}"/>`).join('')}${points.map((value,i)=>`<rect x="${i*42+6}" y="${200-value/ceiling*180}" width="25" height="${value/ceiling*180}" rx="7"><title>${fmt(value)} просмотров</title></rect>`).join('')}</svg></div><div class="chart-dates"><span>${shortDate(M.addDays(M.day(Date.now()),-ui.period))}</span><span>${shortDate(M.day(Date.now()))}</span></div>`)}${panel('От внимания к заявке',`<div class="funnel"><div><span>Просмотры</span><strong>${fmt(Math.round(totals.views*factor))}</strong><i style="width:100%"></i></div><div><span>Переходы</span><strong>${fmt(Math.round(totals.clicks*factor))}</strong><i style="width:66%"></i><small>${totals.views?(totals.clicks/totals.views*100).toFixed(1):0}% от просмотров</small></div><div><span>Заявки</span><strong>${fmt(Math.round(totals.leads*factor))}</strong><i style="width:30%"></i><small>${totals.clicks?(totals.leads/totals.clicks*100).toFixed(1):0}% от переходов</small></div></div><p class="small-help">Ширина ступеней условная. Точные значения показаны рядом.</p>`)}</div><div class="section-head spaced"><h2>Результаты роликов</h2><a href="#leads" class="text-link">Открыть заявки ${icons('arrow')}</a></div><div class="data-table-wrap"><table class="data-table"><thead><tr><th>Ролик</th><th>Статус</th><th>Просмотры</th><th>Переходы</th><th>Заявки</th></tr></thead><tbody>${rows.map(v=>`<tr><td><a href="#video/${e(v.id)}">${e(v.title)}</a><small>${e(v.method)}</small></td><td>${statusBadge(v.status)}</td><td>${fmt(Math.round(v.views*factor))}</td><td>${fmt(Math.round(v.clicks*factor))}</td><td>${fmt(Math.round(v.leads*factor))}</td></tr>`).join('')}</tbody></table></div>${demoNote('Все показатели — демонстрационные. Фильтры показывают пример отчёта, без загрузки статистики из соцсетей.')}`;}
function agentAnswer(question){const t=M.totals(state);const q=question.toLowerCase();if(/снимать|иде|формат|план/.test(q))return {text:`Для ${state.brand.name} стоит протестировать три подачи: «Проблема → решение», «До и после» и короткий список советов. В плане уже ${state.plan.length} идей. Начни с одной проблемы аудитории: ${state.brand.audience}`,action:'niche',label:'Открыть форматы ниши'};if(/заяв|площад|канал/.test(q))return {text:`В демо-проекте у контента ${fmt(t.leads)} заявок с ${fmt(t.clicks)} переходов. Конверсия из перехода в заявку — ${t.clicks?(t.leads/t.clicks*100).toFixed(1):0}%. Посмотри разбивку по роликам и сравни площадки в аналитике.`,action:'analytics',label:'Смотреть аналитику'};return {text:`В твоём демо-проекте ${t.videos} роликов, ${fmt(t.views)} просмотров и ${fmt(t.leads)} заявок. Готовы к публикации: ${state.videos.filter(v=>v.status==='ready').length}. Идей в плане: ${state.plan.length}. Следующий шаг — выбрать готовый ролик или подготовить новый по формату из ниши.`,action:'create',label:'Создать ролик'};}
function agentPage(){return `${heading('Агент-маркетолог','Обсуждай контент, результаты и следующие шаги.')}<div class="agent-intro"><span class="tool-icon">${icons('agent')}</span><div><h2>Твой маркетолог в контексте проекта</h2><p>Бренд, ролики, заявки, площадки и контент-план.</p></div><span class="demo-badge">Демо-ответы</span></div><section class="chat-history" aria-label="Диалог с агентом">${state.chat.length?state.chat.map(message=>`<article class="chat-message ${message.role}"><span class="chat-avatar">${message.role==='user'?'И':icons('spark')}</span><div><span class="chat-author">${message.role==='user'?'Ты':'Агент-маркетолог'}</span><p>${e(message.text)}</p>${message.action?`<a href="#${e(message.action)}" class="btn">${e(message.label)}${icons('arrow')}</a>`:''}</div></article>`).join(''):`<div class="chat-welcome">${icons('spark')}<h2>Что разберём сегодня?</h2><p>Попроси сводку по цифрам, идею ролика или помощь с планом.</p></div>`}</section><div class="suggestions">${['Как дела у проекта?','Что снимать на этой неделе?','Откуда приходят заявки?'].map(q=>`<button type="button" data-action="ask-agent" data-question="${e(q)}">${q}</button>`).join('')}</div><form id="agent-form" class="chat-input"><input name="question" required maxlength="1000" placeholder="Спроси про свои цифры или контент…" aria-label="Сообщение агенту"><button type="submit" class="btn btn-gradient" aria-label="Отправить сообщение">${icons('send')}</button></form><p class="small-help">Локальная демонстрация диалога. AI-модель пока не подключена.</p>`;}
function patternCard(pattern){const product=state.products[0];return `<article class="work-panel pattern-card"><div class="panel-heading"><div><span class="eyebrow">${e(pattern.type)}</span><h2>${e(pattern.title)}</h2><p>Демо: обычно ${fmt(pattern.views)} просмотров · ${pattern.multiplier} к базовому уровню</p></div><button type="button" class="btn btn-gradient" data-action="repeat-pattern" data-id="${pattern.id}">${icons('refresh')}Повторить</button></div><div class="pattern-examples">${[0,1,2].map((n)=>`<div class="mini-cover cover-${(pattern.cover+n-1)%4+1}"><span>ПРИМЕР ${n+1}</span><strong>${e([pattern.hook,pattern.title,'Одна мысль. Один ролик.'][n])}</strong><small>${icons('play')}${fmt(Math.round(pattern.views*(1+n*.38)))}</small></div>`).join('')}</div><div class="pattern-explanation"><p><span>В кадре</span>${e(pattern.idea)}</p><p><span>Хук</span>«${e(pattern.hook)}»</p><p><span>Почему работает</span>${e(pattern.why)}</p><p><span>Для ${e(state.brand.name)}</span>Свяжи формат с продуктом «${e(product?.name||'Твой продукт')}» и покажи один конкретный результат.</p></div></article>`;}
function nichePage(){const analysis=state.analysis;if(analysis.status==='running'){const p=M.progress(analysis.startedAt,10000);const complete=Math.floor(p/10);return `${heading('Агенты разбирают нишу',`${e(state.brand.name)} · демонстрация анализа`)}${panel('',`<div class="job-progress"><div><strong>${complete} из 10 агентов готовы</strong><b>${p}%</b></div><progress value="${p}" max="100"></progress></div><div class="niche-agent-list">${M.agents.map(([name,desc],i)=>`<article class="${i<complete?'done':i===complete?'current':''}"><span>${i<complete?icons('check'):i+1}</span><div><h3>${name}</h3><p>${desc}</p></div><small>${i<complete?'готово':i===complete?'работает':'ждёт'}</small></article>`).join('')}</div>`)}${demoNote('Это демонстрация этапов на данных-примерах. Аккаунты и соцсети не сканируются.')}`;}
if(analysis.status==='ready')return `${heading('Анализ ниши','Форматы и гипотезы для контента твоего бренда.',`<div class="action-row">${button('niche-reset','Новый анализ','refresh')}${button('download-analysis','Скачать отчёт','download')}</div>`)}<div class="analysis-summary"><div><span class="eyebrow">ОТЧЁТ ГОТОВ · ДЕМО</span><h2>${e(state.brand.name)}</h2><p>${e(analysis.description||state.brand.description)}</p></div><div class="action-row">${button('plan-analysis','Составить план','calendar','btn-gradient')}<a href="#studio" class="btn">В Instagram-студию ${icons('arrow')}</a></div></div><div class="metrics">${metric('Аккаунтов','12','Демонстрационный набор','people')}${metric('Публикаций','436','Примеры для анализа','video')}${metric('Сильных форматов','06','Для проверки на твоём бренде','flame')}${metric('Гипотез для теста','03','Результаты не гарантированы','spark')}</div><div class="section-head"><h2>Залетающие форматы</h2><span class="section-meta">Примеры, а не результаты реального поиска</span></div><div class="pattern-list">${M.patterns.map(patternCard).join('')}</div>`;
return `${heading('Анализ ниши','Найди подачу, которая подходит твоему товару и аудитории.')}<div class="split-layout"><section class="work-panel"><form id="niche-form"><div class="tool-heading"><span class="tool-icon">${icons('flame')}</span><div><h2>Разобрать нишу</h2><p>От контекста бренда до форматов, которые можно повторить.</p></div></div>${field('Что за бренд и ниша',`<textarea name="description" rows="4" required maxlength="2000">${e(analysis.description||state.brand.description)}</textarea>`)}${field('Аккаунты или ссылки для ориентира',`<textarea name="competitors" rows="4" maxlength="2000" placeholder="@аккаунт или ссылка, по одному на строку">${e(analysis.competitors)}</textarea>`)}<div class="form-actions"><button class="btn btn-gradient" type="submit">${icons('spark')}Запустить анализ · демо</button></div>${demoNote('В прототипе анализ пройдёт по демонстрационным материалам. Данные аккаунтов не загружаются.')}</form></section><aside class="work-panel"><span class="eyebrow">ЧТО ПОЛУЧИШЬ</span><h2 class="spaced-small">Основа для контента</h2><div class="benefit-list">${[['flame','Повторяемые форматы','Разбор подачи, первых секунд и смысла.'],['chat','Хуки и объяснения','Что цепляет зрителя и почему он досматривает.'],['calendar','План на неделю','Идеи с разными задачами: польза, доверие, оффер.'],['video','Ролик по формуле','Перенос выбранной идеи в создание ролика.']].map(([icon,title,text])=>`<article>${icons(icon)}<div><h3>${title}</h3><p>${text}</p></div></article>`).join('')}</div></aside></div>`;}
const studioTabs=[['profile','Профиль'],['comments','Комментарии'],['audit','Аудит'],['interaction','Взаимодействие'],['repurpose','Переработка'],['carousel','Карусели'],['stories','Сторис'],['week','Неделя']];
function studioOutput(kind){const text=state.studio.outputs[kind];return text?`<section class="work-panel output-panel"><div class="panel-heading"><h2>Заготовка · демо</h2><button type="button" class="btn" data-action="copy-output" data-kind="${kind}">${icons('copy')}Скопировать</button></div><form id="studio-output-form" data-kind="${kind}">${field('Можно отредактировать перед использованием',`<textarea name="output" rows="10" maxlength="10000">${e(text)}</textarea>`)}<div class="form-actions"><button type="submit" class="btn">Сохранить правки</button><button type="button" class="btn" data-action="download-output" data-kind="${kind}">${icons('download')}Скачать текст</button></div></form></section>`:'';}
function studioGenerator(kind,title,description,inputs,label){return `<section class="work-panel"><h2>${title}</h2><p class="body-copy spaced-small">${description}</p><form id="studio-form" data-kind="${kind}">${inputs}<div class="form-actions"><button class="btn btn-gradient" type="submit">${icons('spark')}${label}</button></div><p class="small-help">Локальная заготовка на основе формы и голоса бренда. AI не подключён.</p></form></section>${studioOutput(kind)}`;}
function studioPage(){const kind=ui.studioTab;let body='';if(kind==='profile')body=studioGenerator(kind,'Профиль бренда','Собери понятное описание: кто ты, для кого и что предлагаешь.',`${textField('name','Название',state.brand.name)}${field('О бренде',`<textarea name="source" rows="3">${e(state.brand.description)}</textarea>`)}${textField('cta','Призыв к действию','Посмотри, как работает контент-завод')}`,'Подготовить описание');
if(kind==='comments')body=studioGenerator(kind,'Ответы на комментарии','Подготовь ответ в тоне бренда и отредактируй его перед отправкой.',`${field('Комментарий',select('source',['Сколько времени занимает создание ролика?','Можно использовать свои кадры?','Подойдёт ли это для моей ниши?'],'Можно использовать свои кадры?'))}${field('Тон ответа',select('tone',['Дружелюбно и коротко','Подробно и по делу','С приглашением в диалог'],'Дружелюбно и коротко'))}`,'Подготовить ответ');
if(kind==='audit')body=studioGenerator(kind,'Аудит профиля','Проверка заполнения данных в текущем рабочем пространстве.',`${textField('profile','Профиль',state.brand.handle)}<div class="checklist">${[['Название бренда',Boolean(state.brand.name)],['Описание предложения',Boolean(state.brand.description)],['Аудитория',Boolean(state.brand.audience)],['Голос бренда',Boolean(state.brand.tone)],['Товары и услуги',state.products.length>0]].map(([label,ok])=>`<div>${icons(ok?'check':'close')}<span>${label}</span><small>${ok?'заполнено':'нужно добавить'}</small></div>`).join('')}</div>`,'Собрать рекомендации');
if(kind==='interaction')body=studioGenerator(kind,'Вовлечение и диалоги','Вопросы и механики для разговора с аудиторией.',`${textField('source','Тема','Создание контента без рутины','О чём поговорим?','required maxlength="300"')}${field('Задача',select('goal',['Обсудить проблему','Собрать вопросы','Узнать мнение'],'Обсудить проблему'))}`,'Подготовить идеи');
if(kind==='repurpose')body=studioGenerator(kind,'Одна мысль — разные форматы','Преврати исходный текст в заготовки для ролика, карусели и сторис.',`${field('Исходный текст',`<textarea name="source" rows="6" required maxlength="5000" placeholder="Вставь свой пост, сценарий или заметку"></textarea>`)}`,'Переработать текст');
if(kind==='carousel')body=studioGenerator(kind,'Карусель для бренда','Одна тема, последовательность слайдов и понятный финал.',`${textField('source','Тема карусели','Как превратить идею в неделю контента','','required maxlength="300"')}${field('Слайды',select('count',[[5,'5 слайдов'],[7,'7 слайдов']],5))}`,'Подготовить карусель')+(state.studio.outputs.carousel?`<div class="carousel-preview">${state.studio.outputs.carousel.split('\n\n').filter(Boolean).map((slide,i)=>`<article class="slide-card"><span>${String(i+1).padStart(2,'0')} / ${e(state.brand.name)}</span><h3>${e(slide)}</h3><small>КАРУСЕЛЬ · ПРЕВЬЮ</small></article>`).join('')}</div>`:'');
if(kind==='stories')body=studioGenerator(kind,'Истории на неделю','Сюжеты, опросы и вопросы, которые продолжают основную тему.',`${textField('source','Основная тема','За кадром контент-студии','','required maxlength="300"')}${field('Цель',select('goal',['Познакомить с продуктом','Вовлечь аудиторию','Ответить на вопросы'],'Познакомить с продуктом'))}`,'Подготовить 7 сторис');
if(kind==='week')body=`<section class="work-panel"><div class="panel-heading"><div><h2>Неделя контента</h2><p>Разные задачи: доверие, польза, мнение, история и оффер.</p></div><button class="btn btn-gradient" data-action="studio-week">${icons('spark')}Собрать неделю</button></div><div class="week-content">${M.patterns.map((p,i)=>`<article><span class="number-badge">${i+1}</span><div><span class="eyebrow">${i%2?'КАРУСЕЛЬ':'РИЛС'} · ${p.type}</span><h3>${p.title}</h3><p>${p.idea}</p><small>Хук: «${p.hook}»</small></div><button class="icon-btn" data-action="repeat-pattern" data-id="${p.id}" aria-label="Создать ролик: ${p.title}">${icons('arrow')}</button></article>`).join('')}</div><div class="form-actions">${button('studio-add-plan','Добавить неделю в план','calendar')}<a href="#plan" class="text-link">Открыть план ${icons('arrow')}</a></div></section>${studioOutput('week')}`;
return `${heading('Instagram-студия','Инструменты для ведения бренда — с твоим контекстом и голосом.')}${tabs('studioTab',studioTabs,kind)}<div class="studio-body">${body}</div>`;}
function brandPage(){return `${heading('Бренд и товары','Контекст, который используется в сценариях и контент-плане.')}<div class="brand-layout"><section class="work-panel"><div class="panel-heading"><h2>Голос и контекст бренда</h2><span class="demo-badge">Локально</span></div><form id="brand-form"><div class="form-grid">${textField('name','Название бренда',state.brand.name,'','required maxlength="80"')}${textField('handle','Профиль',state.brand.handle,'@brand','maxlength="100"')}</div>${field('Описание бренда и предложения',`<textarea name="description" rows="3" required maxlength="2000">${e(state.brand.description)}</textarea>`)}${field('Кому помогаем',`<textarea name="audience" rows="3" maxlength="2000">${e(state.brand.audience)}</textarea>`)}${field('Голос бренда',`<textarea name="tone" rows="4" maxlength="2000">${e(state.brand.tone)}</textarea>`)}${textField('website','Сайт или ссылка',state.brand.website,'https://…','type="url" maxlength="300"')}<div class="form-actions"><button type="submit" class="btn btn-gradient">${icons('check')}Сохранить бренд</button></div></form></section><aside><section class="work-panel"><span class="eyebrow">МАТЕРИАЛЫ БРЕНДА</span><h2 class="spaced-small">Товары и услуги</h2><p class="body-copy spaced-small">Фото, исходные видео и описания для создания контента.</p>${state.products.map(p=>`<article class="product-card"><span class="product-icon">${icons('box')}</span><div><h3>${e(p.name)}</h3><p>${e(p.description)}</p><small>${p.assets?.length||0} файлов</small></div><button class="icon-btn" data-action="edit-product" data-id="${e(p.id)}" aria-label="Редактировать ${e(p.name)}">${icons('edit')}</button></article>`).join('')}<button class="btn full-width" data-action="add-product">${icons('plus')}Добавить товар</button></section></aside></div>`;}
function channelsPage(){return `${heading('Каналы и API','Куда выходит контент и какие сервисы участвуют в создании.')}<div class="section-head"><h2>${icons('publications')}Каналы публикации</h2><span class="section-meta">${state.channels.filter(c=>c.connected).length} демо-канала</span></div><div class="channel-grid">${state.channels.map(c=>`<article class="work-panel channel-card"><div class="panel-heading"><span class="channel-icon">${icons(c.id==='telegram'?'send':c.id==='instagram'?'studio':'videos')}</span><span class="connection-status ${c.connected?'connected':''}">${c.connected?'Демо-канал':'Не добавлен'}</span></div><h2>${c.platform}</h2><p>${c.connected?e(c.handle):'Добавь профиль для демонстрации публикаций'}</p><button class="btn ${c.connected?'':'btn-gradient'}" data-action="channel-dialog" data-id="${c.id}">${icons(c.connected?'edit':'plus')}${c.connected?'Настроить':'Добавить канал'}</button></article>`).join('')}</div><div class="section-head spaced"><h2>Сервисы создания контента</h2><a href="#checks" class="text-link">Проверка конфигурации ${icons('arrow')}</a></div><div class="data-table-wrap"><table class="data-table"><thead><tr><th>Сервис</th><th>Задача</th><th>Состояние</th></tr></thead><tbody>${[['AI-модель','Анализ, сценарии и маркетолог'],['Озвучка','Синтез речи в голосе бренда'],['Генерация видео','Создание сцен и аватаров'],['Рендер','Монтаж, музыка и субтитры'],['Публикация','Отправка в подключённые аккаунты']].map(([name,desc])=>`<tr><td>${name}</td><td>${desc}</td><td><span class="connection-status">Сервер не подключён</span></td></tr>`).join('')}</tbody></table></div>${demoNote('Фронтенд не хранит API-ключи и не выполняет OAuth. Добавление канала создаёт только запись в демо-проекте.')}`;}
function leadsPage(){const rows=state.leads.filter(l=>ui.leadsFilter==='all'||l.status===ui.leadsFilter);return `${heading('Заявки и команда','Источник, ответственный и следующий шаг по каждому обращению.')}<div class="lead-summary">${[['new','Новые'],['progress','В работе'],['done','Завершены']].map(([status,label])=>`<button type="button" data-action="leads-filter" data-value="${status}" class="work-panel ${ui.leadsFilter===status?'selected':''}"><span>${label}</span><strong>${state.leads.filter(l=>l.status===status).length}</strong></button>`).join('')}</div><div class="section-head">${tabs('leadsFilter',[['all','Все заявки'],['new','Новые'],['progress','В работе'],['done','Завершены']],ui.leadsFilter)}<span class="section-meta">Демонстрационные обращения</span></div><div class="data-table-wrap"><table class="data-table"><thead><tr><th>Контакт</th><th>Сообщение</th><th>Источник</th><th>Статус</th><th>Ответственный</th></tr></thead><tbody>${rows.map(l=>`<tr class="clickable-row" data-action="open-lead" data-id="${l.id}"><td><button class="table-text-button" type="button" data-action="open-lead" data-id="${l.id}">${e(l.name)}</button><small>${shortDate(M.day(l.createdAt))}</small></td><td class="message-cell">${e(l.text)}</td><td>${e(l.channel)}<small>${e(state.videos.find(v=>v.id===l.videoId)?.title||'Ролик')}</small></td><td><span class="lead-status ${l.status}">${{new:'Новая',progress:'В работе',done:'Завершена'}[l.status]}</span></td><td>${e(l.assignee)}</td></tr>`).join('')||'<tr><td colspan="5">Заявок с таким статусом нет.</td></tr>'}</tbody></table></div>${demoNote('Можно менять статусы, назначать ответственного и сохранять заметки. Сообщения клиентам не отправляются.')}`;}
function checkRows(){return [{name:'Интерфейс',detail:'Все основные разделы доступны',status:'ok'},{name:'Локальное хранилище',detail:storageWarning?'Сохранение заблокировано браузером':'Настройки и изменения сохраняются в браузере',status:storageWarning?'warning':'ok'},{name:'Бренд и товары',detail:state.products.length?`${state.products.length} товара · ${state.brand.name}`:'Добавь товар или услугу',status:state.products.length?'ok':'warning'},{name:'Каналы публикации',detail:`${state.channels.filter(c=>c.connected).length} демо-канала, без авторизации в соцсетях`,status:'demo'},{name:'AI, озвучка и генерация',detail:'Нужен серверный API. Реальные запросы не выполняются.',status:'missing'},{name:'Отправка публикаций',detail:'В прототипе записи сохраняются только локально',status:'missing'}];}
function checksPage(){return `${heading('Проверка API','Проверка готовности интерфейса и точек будущего подключения.',button('run-checks','Проверить конфигурацию','refresh','btn-gradient'))}${state.checks?`<p class="small-help">Последняя проверка: ${new Intl.DateTimeFormat('ru-RU',{dateStyle:'short',timeStyle:'short',timeZone:'Europe/Moscow'}).format(new Date(state.checks.at))}</p>`:''}<section class="work-panel check-results">${(state.checks?.rows||checkRows()).map(row=>`<article><span class="check-indicator ${row.status}">${icons(row.status==='ok'?'check':row.status==='demo'?'publications':'plug')}</span><div><h3>${row.name}</h3><p>${e(row.detail)}</p></div><span class="connection-status ${row.status==='ok'?'connected':''}">${{ok:'Готово',warning:'Нужно внимание',demo:'Демо',missing:'Не подключено'}[row.status]}</span></article>`).join('')}</section><div class="action-row spaced">${button('export-checks','Скачать диагностику','download')}<a href="#channels" class="btn">Настроить подключения ${icons('arrow')}</a></div>${demoNote('Проверяются только локальные данные. Проверка доступности реальных API начнёт работать после подключения сервера.')}`;}
function resetWizard(input={}){wizard={title:'',brief:'',productId:state.products[0]?.id||'',format:M.platforms[0],duration:30,method:'Проблема → решение',voice:'Спокойный',language:'Русский',assets:[],...input};wizardStep=1;}
function captureWizard(){const form=$('#wizard-form');if(form)Object.assign(wizard,Object.fromEntries(new FormData(form)));}
function commitWizard(start){captureWizard();const product=state.products.find(p=>p.id===wizard.productId);const assets=[...new Map([...(product?.assets||[]),...(wizard.assets||[])].map(a=>[a.id,a])).values()];const video=M.createVideo(state,{...wizard,assets});if(wizard.planId){const item=state.plan.find(p=>p.id===wizard.planId);if(item)item.videoId=video.id;}if(start)M.startVideo(state,video.id);save();resetWizard();go('video',video.id);toast(start?'Началась демонстрация сборки':'Черновик сохранён');}
function makePlanVideo(planId){const item=state.plan.find(p=>p.id===planId);if(!item)return;const existing=state.videos.find(v=>v.id===item.videoId);if(existing){go('video',existing.id);return;}resetWizard({title:item.title,brief:item.description,method:item.type,planId:item.id});go('create');}
function publishDialog(videoId){const v=state.videos.find(v=>v.id===videoId);if(!v)return;const caption=$('#caption-form textarea');if(caption){v.caption=caption.value;save();}const channels=state.channels.filter(c=>c.connected);openModal('Опубликовать',`<form id="publish-form" data-id="${e(v.id)}"><p class="body-copy">Выбери площадки и время для записи в демо-проекте.</p><div class="channel-options">${channels.map((c,i)=>`<label><input type="checkbox" name="channelIds" value="${c.id}" ${i===0?'checked':''}><span class="channel-icon">${icons(c.id==='instagram'?'studio':'videos')}</span><span><strong>${e(c.platform)}</strong><small>${e(c.handle)}</small></span><span class="demo-badge">Демо</span></label>`).join('')||'<a href="#channels" class="text-link" data-action="close-modal">Сначала добавь демо-канал</a>'}</div>${field('Когда',select('publishMode',[['now','Сейчас'],['best','В лучшее время · демо'],['schedule','Выбрать дату и время']],'now'))}<div class="form-grid" id="publish-date" hidden>${textField('date','Дата',M.addDays(M.day(Date.now()),1),'','type="date"')}${textField('time','Время по Москве','12:00','','type="time"')}</div>${formError()}<button class="btn btn-gradient full-width" type="submit">${icons('publications')}Добавить демо-публикацию</button><p class="small-help">Без отправки в соцсети. Запись будет видна в карточке ролика и расписании.</p></form>`);}
function productDialog(productId){const product=state.products.find(p=>p.id===productId);productFiles=M.clone(product?.assets||[]);openModal(product?'Редактировать товар':'Новый товар или услуга',`<form id="product-form" data-id="${e(product?.id||'')}">${textField('name','Название',product?.name||'','','required maxlength="100"')}${field('Описание',`<textarea name="description" rows="4" maxlength="2000" required>${e(product?.description||'')}</textarea>`)}<div class="upload-zone compact">${icons('upload')}<strong>Фото и исходные видео</strong><label class="btn"><input id="product-files" type="file" accept="image/*,video/*" multiple>Выбрать файлы</label></div><div id="product-assets">${assetList(productFiles)}</div><p class="small-help">Файлы доступны в текущей сессии браузера. После перезагрузки сохранятся только названия материалов.</p>${formError()}<button type="submit" class="btn btn-gradient full-width">Сохранить товар</button></form>`);}
function leadDialog(leadId){const lead=state.leads.find(l=>l.id===leadId);if(!lead)return;openModal(`Заявка · ${e(lead.name)}`,`<p class="lead-message">${e(lead.text)}</p><div class="small-help">${e(lead.channel)} · ${shortDate(M.day(lead.createdAt))}</div><form id="lead-form" data-id="${lead.id}"><div class="form-grid">${field('Статус',select('status',[['new','Новая'],['progress','В работе'],['done','Завершена']],lead.status))}${field('Ответственный',select('assignee',['Не назначен','Илья','Редактор'],lead.assignee))}</div>${field('Заметка для команды',`<textarea name="note" rows="4" maxlength="2000">${e(lead.note)}</textarea>`)}<div class="form-actions"><button class="btn btn-gradient" type="submit">Сохранить</button>${state.videos.some(v=>v.id===lead.videoId)?`<a href="#video/${e(lead.videoId)}" class="btn" data-action="close-modal">Открыть ролик ${icons('arrow')}</a>`:''}</div></form>`);}
function channelDialog(channelId){const c=state.channels.find(c=>c.id===channelId);if(!c)return;openModal(c.platform,`<form id="channel-form" data-id="${c.id}">${textField('handle','Профиль или название канала',c.handle,'@brand','required maxlength="100"')}${demoNote('Это настройка демонстрационного канала. Вход в аккаунт и выдача разрешений не выполняются.')}<div class="form-actions"><button type="submit" class="btn btn-gradient">${c.connected?'Сохранить':'Добавить демо-канал'}</button>${c.connected?`<button type="button" class="btn" data-action="disconnect-channel" data-id="${c.id}">Отключить в демо</button>`:''}</div></form>`);}
let productFiles=[];
function buildStudioOutput(kind,data){const source=String(data.source||state.brand.description).trim();const name=state.brand.name;if(kind==='profile')return `${data.name||name}\n\n${source}\nДля ${state.brand.audience}\n\n${data.cta||'Посмотри, как это работает.'}`;if(kind==='comments')return `Вопрос: ${source}\n\n${source.includes('кадры')?'Да, можно использовать свои фото и видео. Добавь их в материалы товара или при создании ролика.':source.includes('времени')?'Время зависит от формата, исходных материалов и выбранного способа создания. Лучше начать с одного короткого ролика.':'Начни с одного продукта и задачи твоей аудитории. На примере ролика будет проще понять, подходит ли формат.'}\n\nЕсли хочешь, расскажи немного о своей задаче — подберём подходящий пример.`;if(kind==='audit')return `Профиль: ${data.profile||state.brand.handle}\n\n1. В первой строке объясни, какую задачу решает ${name}.\n2. Добавь понятный результат и один пример.\n3. Оставь один следующий шаг: посмотреть демо или задать вопрос.\n4. Проверь, что описание связано с продуктом «${state.products[0]?.name||'Твой продукт'}».\n\nЭто рекомендации по данным проекта. Реальная страница профиля не проверялась.`;if(kind==='interaction')return `Тема: ${source}\n\n1. Опрос: что занимает больше времени — идеи или монтаж?\n2. Вопрос: какой ролик давно хочешь снять, но откладываешь?\n3. Обсуждение: покажи свой процесс и попроси поделиться одним полезным шагом.\n4. Завершение: ответь на повторяющийся вопрос отдельной публикацией.`;if(kind==='repurpose')return `РИЛС\nХук: «Что стоит знать об этой теме?»\nОсновная мысль: ${source.slice(0,700)}\nФинал: сохрани, чтобы вернуться к этой мысли.\n\nКАРУСЕЛЬ\n1. Вопрос аудитории.\n2. Ключевая мысль.\n3. Конкретный пример.\n4. Как применить.\n5. Один следующий шаг.\n\nСТОРИС\nВопрос → пример из процесса → короткий ответ → приглашение обсудить.`;if(kind==='carousel')return Array.from({length:Number(data.count)||5},(_,i)=>[`${source}\nЧто важно знать?`,'Начни с одной задачи аудитории.','Объясни одну мысль простыми словами.','Покажи конкретный пример.','Добавь один шаг, который можно повторить.','Собери вывод в короткую фразу.','Сохрани и попробуй на своём контенте.'][i]||'Сохрани и попробуй на своём контенте.').join('\n\n');if(kind==='stories')return ['Знакомство: покажи, над чем работаешь.','Опрос: какая часть процесса сложнее?','Процесс: один короткий кадр за работой.','Польза: один совет по теме.','Ответ на вопрос аудитории.','Результат: что получилось.','Диалог: предложи задать вопрос.'].map((text,i)=>`${i+1}. ${text}\nТема: ${source}`).join('\n\n');return M.patterns.map((p,i)=>`${i+1}. ${p.type}: ${p.title}\nХук: ${p.hook}\n${p.idea}`).join('\n\n');}
function sendQuestion(question){question=String(question||'').trim().slice(0,1000);if(!question)return;state.chat.push({role:'user',text:question},{role:'assistant',...agentAnswer(question)});state.chat=state.chat.slice(-40);save();render(true);$('.chat-history')?.lastElementChild?.scrollIntoView({block:'nearest'});}
function downloadMaterials(v){const original=(v.assets||[]).find(a=>a.type.startsWith('video')&&media.has(a.id));openModal('Скачать материалы',`<p class="body-copy">Доступные материалы ролика «${e(v.title)}».</p><div class="download-options"><button class="btn" data-action="download-script" data-id="${e(v.id)}">${icons('file')}Сценарий · TXT</button><button class="btn" data-action="download-cover" data-id="${e(v.id)}">${icons('download')}Обложка · SVG</button>${original?`<a class="btn" download="${e(original.name)}" href="${media.get(original.id)}">${icons('video')}Исходное видео</a>`:'<button class="btn" disabled>Готовое видео · пока недоступно</button>'}</div><p class="small-help">Готовое видео появится после подключения генерации и рендера. Сейчас доступны сценарий и обложка-макет.</p>`);}
function downloadCover(v){const words=v.title.split(/\s+/);const lines=[];let line='';for(const word of words){if((line+' '+word).length>18&&line){lines.push(line);line=word;}else line=(line+' '+word).trim();}if(line)lines.push(line);const svg=`<svg xmlns="http://www.w3.org/2000/svg" width="1080" height="1920" viewBox="0 0 1080 1920"><defs><linearGradient id="blue" x2="1" y2="1"><stop stop-color="#153772"/><stop offset="1" stop-color="#397BFA"/></linearGradient></defs><rect width="1080" height="1920" fill="url(#blue)"/><circle cx="1110" cy="1750" r="480" fill="none" stroke="#8DC3FF" stroke-opacity=".3" stroke-width="160"/><text x="100" y="140" fill="white" font-size="40" font-family="Arial,sans-serif">${e(state.brand.name)}</text><text x="100" y="650" fill="white" font-size="90" font-weight="bold" font-family="Arial,sans-serif">${lines.slice(0,8).map((s,i)=>`<tspan x="100" dy="${i?'115':'0'}">${e(s)}</tspan>`).join('')}</text><text x="100" y="1800" fill="#C6E0FF" font-size="24" font-family="Arial,sans-serif">ПРЕВЬЮ ОБЛОЖКИ</text></svg>`;download('mill-cover.svg',svg,'image/svg+xml;charset=utf-8');}
const actions={
  'close-modal':el=>{$('#modal').close();if(el.tagName==='A')location.hash=el.getAttribute('href');},
  'undo':()=>{if(undoState){state=undoState;undoState=null;save();render();toast('Изменение отменено');}},
  'wizard-back':()=>{captureWizard();wizardStep=Math.max(1,wizardStep-1);render();},
  'save-draft':()=>commitWizard(false),
  'start-video':()=>{M.startVideo(state,route().id);save();render();},
  'duplicate-video':()=>{const v=state.videos.find(v=>v.id===route().id);if(!v)return;const next=M.createVideo(state,{...v,title:`${v.title} · другой вариант`,script:v.script,cover:5});save();go('video',next.id);toast('Создан отдельный черновик');},
  'delete-video':()=>{rememberUndo();M.removeVideo(state,route().id);save();go('videos');toast('Ролик удалён из демо-проекта',true);},
  'download-materials':()=>{const v=state.videos.find(v=>v.id===route().id);if(v)downloadMaterials(v);},
  'download-script':el=>{const v=state.videos.find(v=>v.id===el.dataset.id);if(v)download('mill-script.txt',`${v.title}\n\n${v.script}\n\nПодпись:\n${v.caption}`);},
  'download-cover':el=>{const v=state.videos.find(v=>v.id===el.dataset.id);if(v)downloadCover(v);},
  'copy-script':async()=>{const form=$('#script-form');const v=state.videos.find(v=>v.id===route().id);await copyText(form?.elements.script.value||v?.script||'');},
  'save-caption':()=>{const form=$('#caption-form');if(form){const v=state.videos.find(v=>v.id===form.dataset.id);v.caption=form.elements.caption.value;save();toast('Подпись сохранена');}},
  'open-publish':()=>publishDialog(route().id),
  'publish-analytics':()=>{$('#modal').close();go('analytics');},
  'autopilot':()=>{state.autopilot.enabled=!state.autopilot.enabled;save();render(true);toast(state.autopilot.enabled?'Автопилот включён в демо-проекте':'Автопилот выключен');},
  'plan-count':el=>{state.autopilot.count=Number(el.dataset.value);save();render(true);},
  'plan-quick':()=>addPlan('quick'),
  'plan-analysis':()=>{if(state.analysis.status!=='ready'){go('niche');toast('Сначала запусти демонстрацию анализа ниши');return;}addPlan('analysis');},
  'clear-plan':()=>{rememberUndo();state.plan=[];save();render(true);toast('Список идей очищен. Расписание публикаций сохранено.',true);},
  'make-plan-video':el=>makePlanVideo(el.dataset.id),
  'week-prev':()=>{ui.week--;render(true);},'week-next':()=>{ui.week++;render(true);},
  'ask-agent':el=>sendQuestion(el.dataset.question),
  'repeat-pattern':el=>{const p=M.patterns.find(p=>p.id===el.dataset.id);if(p){resetWizard({title:p.title,brief:p.idea,method:p.type,cover:p.cover});go('create');}},
  'niche-reset':()=>{state.analysis.status='idle';save();render();},
  'download-analysis':()=>download('mill-niche-demo.txt',`Демонстрационный отчёт · ${state.brand.name}\nЭто пример, не реальное исследование аккаунтов.\n\n`+M.patterns.map(p=>`${p.title}\nХук: ${p.hook}\nПочему: ${p.why}\nИдея: ${p.idea}`).join('\n\n')),
  'studio-week':()=>{state.studio.outputs.week=buildStudioOutput('week',{});save();render(true);toast('Заготовка недели подготовлена');},
  'studio-add-plan':()=>addPlan('studio'),
  'copy-output':async el=>copyText(state.studio.outputs[el.dataset.kind]||''),
  'download-output':el=>download(`mill-${el.dataset.kind}.txt`,state.studio.outputs[el.dataset.kind]||''),
  'add-product':()=>productDialog(),
  'edit-product':el=>productDialog(el.dataset.id),
  'channel-dialog':el=>channelDialog(el.dataset.id),
  'disconnect-channel':el=>{const c=state.channels.find(c=>c.id===el.dataset.id);if(c)c.connected=false;save();$('#modal').close();render();toast('Демо-канал отключён');},
  'open-lead':el=>leadDialog(el.dataset.id),
  'leads-filter':el=>{ui.leadsFilter=el.dataset.value;render(true);},
  'run-checks':()=>{state.checks={at:Date.now(),rows:checkRows()};save();render(true);toast('Локальная конфигурация проверена');},
  'export-checks':()=>download('mill-diagnostics.json',JSON.stringify({mode:'frontend-demo',at:new Date().toISOString(),checks:checkRows()},null,2),'application/json'),
};
function addPlan(source){const added=M.buildPlan(state,state.autopilot.count,source);save();go('plan');toast(added.length?`Добавлено идей: ${added.length}`:'Эти идеи уже есть в плане');}
async function copyText(text){try{await navigator.clipboard.writeText(text);toast('Текст скопирован');}catch{toast('Копирование недоступно. Выдели текст вручную.');}}
function onError(error){const target=$('#form-error');if(target)target.textContent=error.message;else toast(error.message||'Не удалось выполнить действие.');}
document.addEventListener('click',async event=>{if(event.target.closest('#export-tokens')){download('mill-design-tokens.json',JSON.stringify({theme,colors:Object.fromEntries(getPalette()),font:'Manrope',radii:[10,16,18,22]},null,2),'application/json');return;}const themeChoice=event.target.closest('[data-theme-choice]');if(themeChoice){applyTheme(themeChoice.dataset.themeChoice);if(route().page==='style')render(true);return;}const tab=event.target.closest('[data-tab-group]');if(tab){ui[tab.dataset.tabGroup]=tab.dataset.tab;render(true);return;}const create=event.target.closest('[data-create]');if(create){resetWizard();go('create');return;}if(event.target.closest('#menu-toggle')){setMenu(!$('#sidebar').classList.contains('open'));return;}const action=event.target.closest('[data-action]');if(action){event.preventDefault();try{await actions[action.dataset.action]?.(action);}catch(error){onError(error);}return;}if($('#sidebar').classList.contains('open')&&!event.target.closest('.sidebar')){setMenu(false);}});
document.addEventListener('input',event=>{if(event.target.id==='video-search'){ui.query=event.target.value;$('#video-library').innerHTML=filteredVideos();}if(event.target.closest('#wizard-form')&&event.target.name)wizard[event.target.name]=event.target.value;});
document.addEventListener('change',event=>{const el=event.target;if(el.id==='analytics-period'){ui.period=Number(el.value);render(true);}if(el.id==='analytics-channel'){ui.analyticsChannel=el.value;render(true);}if(el.name==='publishMode'){const show=el.value!=='now';$('#publish-date').hidden=!show;$('#publish-date').classList.toggle('suggested-time',el.value==='best');if(el.value==='best'){$('#publish-date input[name=date]').value=M.addDays(M.day(Date.now()),1);$('#publish-date input[name=time]').value='12:00';}}if(['wizard-files','product-files'].includes(el.id)){const files=[...el.files].slice(0,12).filter(f=>f.type.startsWith('image/')||f.type.startsWith('video/')).map(file=>{const id=M.id('asset');media.set(id,URL.createObjectURL(file));return {id,name:file.name,type:file.type,size:file.size};});if(el.id==='wizard-files'){captureWizard();wizard.assets=[...(wizard.assets||[]),...files].slice(0,12);render(true);}else{productFiles=[...productFiles,...files].slice(0,12);$('#product-assets').innerHTML=assetList(productFiles);}}});
document.addEventListener('submit',event=>{event.preventDefault();const form=event.target;const data=Object.fromEntries(new FormData(form));try{
  if(form.id==='wizard-form'){captureWizard();if(wizardStep<3){wizardStep++;render();}else commitWizard(true);}
  if(form.id==='brand-form'){Object.assign(state.brand,data);save();toast('Контекст и голос бренда сохранены');}
  if(form.id==='script-form'){const v=state.videos.find(v=>v.id===form.dataset.id);if(v){v.script=data.script;save();toast('Сценарий сохранён');}}
  if(form.id==='caption-form'){const v=state.videos.find(v=>v.id===form.dataset.id);if(v){v.caption=data.caption;save();toast('Подпись сохранена');}}
  if(form.id==='agent-form')sendQuestion(data.question);
  if(form.id==='niche-form'){Object.assign(state.analysis,data,{status:'running',startedAt:Date.now()});save();render();}
  if(form.id==='studio-form'){state.studio.outputs[form.dataset.kind]=buildStudioOutput(form.dataset.kind,data);save();render(true);toast('Демонстрационная заготовка готова');}
  if(form.id==='studio-output-form'){state.studio.outputs[form.dataset.kind]=data.output;save();render(true);toast('Правки сохранены');}
  if(form.id==='product-form'){let p=state.products.find(p=>p.id===form.dataset.id);if(!p){p={id:M.id('product')};state.products.push(p);}Object.assign(p,{name:data.name.trim(),description:data.description.trim(),assets:productFiles});save();$('#modal').close();render();toast('Товар сохранён');}
  if(form.id==='channel-form'){const c=state.channels.find(c=>c.id===form.dataset.id);Object.assign(c,{handle:data.handle.trim(),connected:true,demo:true});save();$('#modal').close();render();toast('Демо-канал сохранён');}
  if(form.id==='lead-form'){const lead=state.leads.find(l=>l.id===form.dataset.id);Object.assign(lead,data);save();$('#modal').close();render(true);toast('Заявка обновлена');}
  if(form.id==='publish-form'){const ids=new FormData(form).getAll('channelIds');const when=data.publishMode==='now'?{}:{date:data.date,time:data.time};const pubs=M.publish(state,form.dataset.id,{channelIds:ids,...when});save();$('#modal').close();render(true);openModal(pubs.some(p=>p.status==='planned')?'Добавлено в расписание':'Демо-публикация добавлена',`<div class="success-state">${icons('check')}<p>${pubs.length?`Записей в проекте: ${pubs.length}.`:'Такая публикация уже есть в проекте.'}</p><p>Отправка во внешние соцсети не выполнялась.</p></div><div class="form-actions">${button('close-modal','Открыть ролик','video','btn-gradient')}${button('publish-analytics','Аналитика','chart')}</div>`);}
}catch(error){onError(error);}});
$('#modal').addEventListener('click',event=>{if(event.target===$('#modal')){const r=event.target.getBoundingClientRect();if(event.clientX<r.left||event.clientX>r.right||event.clientY<r.top||event.clientY>r.bottom)event.target.close();}});
document.addEventListener('keydown',event=>{if((event.ctrlKey||event.metaKey)&&event.key.toLowerCase()==='k'){event.preventDefault();if(!$('#modal').open){resetWizard();go('create');}}if(event.key==='Escape'){setMenu(false);}});
function setMenu(open){const sidebar=$('#sidebar');sidebar.classList.toggle('open',open);$('#menu-toggle').setAttribute('aria-expanded',String(open));sidebar.inert=window.matchMedia('(max-width: 640px)').matches&&!open;}
function render(preserveScroll=false){const current=route();const labels=Object.fromEntries(navItems.map(([id,label])=>[id,label]));labels.create='Создать ролик';labels.video='Ролик';labels.style='Дизайн-система';const pages={overview:overviewPage,videos:videosPage,create:createPage,video:()=>videoPage(current.id),plan:planPage,analytics:analyticsPage,agent:agentPage,niche:nichePage,studio:studioPage,brand:brandPage,channels:channelsPage,leads:leadsPage,checks:checksPage,style:stylePage};const page=pages[current.page]?current.page:'overview';$('#page-label').textContent=labels[page];document.title=`${labels[page]} · mill`;document.querySelectorAll('[data-nav]').forEach(a=>{const active=a.dataset.nav===(page==='video'?'videos':page);a.classList.toggle('active',active);if(active)a.setAttribute('aria-current','page');else a.removeAttribute('aria-current');});disposeMascot();main.innerHTML=pages[page]();disposeMascot=window.MillMascot.mount(main.querySelector('[data-mill-mascot]'));const count=$('#video-count');if(count)count.textContent=state.videos.length;setMenu(false);if(!preserveScroll)window.scrollTo(0,0);}
function initialise(){applyTheme(theme,false);$('#main-nav').innerHTML=navItems.map(([id,label,icon])=>`<a href="#${id}" data-nav="${id}">${icons(icon)}${label}${id==='videos'?`<span class="nav-count" id="video-count">${state.videos.length}</span>`:''}</a>`).join('');resetWizard();M.advance(state);save();render();}
window.addEventListener('hashchange',()=>render());
window.matchMedia('(max-width: 640px)').addEventListener('change',()=>setMenu(false));
setInterval(()=>{const r=route();const working=r.page==='niche'&&state.analysis.status==='running'||r.page==='video'&&state.videos.some(v=>v.id===r.id&&v.status==='generating');const completed=M.advance(state);if(completed){save();toast('Демонстрация завершена. Результат сохранён в проекте.');}if((working||completed&&['overview','videos','analytics','plan'].includes(r.page))&&!$('#modal').open&&!['INPUT','TEXTAREA','SELECT'].includes(document.activeElement.tagName))render(true);},700);
window.addEventListener('beforeunload',()=>media.forEach(url=>URL.revokeObjectURL(url)));
initialise();
